16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.time.Period;
27	import java.time.temporal.ChronoUnit;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "address")
42	    @NotEmpty
43	    private String address;
44	
45	    @Column(name = "city")
46	    @NotEmpty
47	    private String city;
48	
49	    @Column(name = "postcode")
50	    private String postcode;
51	
52	    @Column(name = "telephone")
53	    @NotEmpty
54	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
55	    private String telephone;
56	
57	    @Column(name = "email")
58	    @Email
59	    private String email;
60	
61	    @Column(name = "registration_date")
62	    private LocalDate registrationDate;
63	
64	    @Column(name = "birth_date")
65	    private LocalDate birthDate;
66	
67	    @Column(name = "customer_code")
68	    private String customerCode;
69	
70	    @Column(name = "household_id")
71	    private String householdId;
72	
73	    @Column(name = "namesake_count")
74	    private Integer namesakeCount;
75	
76	    @Column(name = "bulk_signup_warning")
77	    private Boolean bulkSignupWarning;
78	
79	    @Column(name = "household_size")
80	    private Integer householdSize;
81	
82	    @Column(name = "possible_duplicate")
83	    private Boolean possibleDuplicate;
84	
85	    @Column(name = "possible_duplicate_of")
86	    private Integer possibleDuplicateOf;
87	
88	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
89	    private Set<Pet> pets;
90	
91	    public String getAddress() {
92	        return this.address;
93	    }
94	
95	    public void setAddress(String address) {
96	        this.address = address;
97	    }
98	
99	    public String getCity() {
100	        return this.city;
101	    }
102	
103	    public void setCity(String city) {
104	        this.city = city;
105	    }
106	
107	    public String getPostcode() {
108	        return this.postcode;
109	    }
110	
111	    public void setPostcode(String postcode) {
112	        this.postcode = postcode;
113	    }
114	
115	    public String getTelephone() {
116	        return this.telephone;
117	    }
118	
119	    public void setTelephone(String telephone) {
120	        this.telephone = telephone;
121	    }
122	
123	    public String getEmail() {
124	        return this.email;
125	    }
126	
127	    public void setEmail(String email) {
128	        this.email = email == null ? null : email.toLowerCase();
129	    }
130	
131	    public LocalDate getRegistrationDate() {
132	        return this.registrationDate;
133	    }
134	
135	    public void setRegistrationDate(LocalDate registrationDate) {
136	        this.registrationDate = registrationDate;
137	    }
138	
139	    public LocalDate getBirthDate() {
140	        return this.birthDate;
141	    }
142	
143	    public void setBirthDate(LocalDate birthDate) {
144	        this.birthDate = birthDate;
145	    }
146	
147	    /**
148	     * The owner's age band derived from {@link #birthDate} relative to the
149	     * {@link #registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
150	     * and {@code 'SENIOR'} at 65 or older. Returns {@code null} when no birthDate is set. The age
151	     * is the number of complete years between the birthDate and the registrationDate (or the
152	     * current date when the registrationDate is not yet set).
153	     */
154	    public String getAgeBand() {
155	        if (this.birthDate == null) {
156	            return null;
157	        }
158	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
159	        int years = Period.between(this.birthDate, reference).getYears();
160	        if (years < 18) {
161	            return "MINOR";
162	        }
163	        if (years < 65) {
164	            return "ADULT";
165	        }
166	        return "SENIOR";
167	    }
168	
169	    public String getCustomerCode() {
170	        return this.customerCode;
171	    }
172	
173	    public void setCustomerCode(String customerCode) {
174	        this.customerCode = customerCode;
175	    }
176	
177	    public String getHouseholdId() {
178	        return this.householdId;
179	    }
180	
181	    public void setHouseholdId(String householdId) {
182	        this.householdId = householdId;
183	    }
184	
185	    public Integer getNamesakeCount() {
186	        return this.namesakeCount;
187	    }
188	
189	    public void setNamesakeCount(Integer namesakeCount) {
190	        this.namesakeCount = namesakeCount;
191	    }
192	
193	    public Boolean getBulkSignupWarning() {
194	        return this.bulkSignupWarning;
195	    }
196	
197	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
198	        this.bulkSignupWarning = bulkSignupWarning;
199	    }
200	
201	    public Integer getHouseholdSize() {
202	        return this.householdSize;
203	    }
204	
205	    public void setHouseholdSize(Integer householdSize) {
206	        this.householdSize = householdSize;
207	    }
208	
209	    public Boolean getPossibleDuplicate() {
210	        return this.possibleDuplicate;
211	    }
212	
213	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
214	        this.possibleDuplicate = possibleDuplicate;
215	    }
216	
217	    public Integer getPossibleDuplicateOf() {
218	        return this.possibleDuplicateOf;
219	    }
220	
221	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
222	        this.possibleDuplicateOf = possibleDuplicateOf;
223	    }
224	
225	    /**
226	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
227	     */
228	    public String getDisplayName() {
229	        return this.getLastName() + ", " + this.getFirstName();
230	    }
231	
232	    /**
233	     * The owner's initials: the upper-cased first letters of firstName and lastName,
234	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
235	     */
236	    public String getInitials() {
237	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
238	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
239	    }
240	
241	    /**
242	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is the
243	     * last two digits of the registrationDate year, e.g. {@code 'NSW-3C1A9F2B-M26'}.
244	     */
245	    public String getMembershipNumber() {
246	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
247	    }
248	
249	    /**
250	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) computed over the decimal digits
251	     * contained in the owner's {@link #customerCode}.
252	     */
253	    public int getCheckDigit() {
254	        return luhnCheckDigit(this.customerCode);
255	    }
256	
257	    /**
258	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
259	     * contained in {@code value}. Reading the digits right to left, every second one is
260	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
261	     * digits are summed, and the check digit is the amount that must be added to that sum to
262	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
263	     * the digit is taken over exactly the digits the string carries.
264	     */
265	    private static int luhnCheckDigit(String value) {
266	        int sum = 0;
267	        boolean doubling = true;
268	        for (int i = value.length() - 1; i >= 0; i--) {
269	            char c = value.charAt(i);
270	            if (c < '0' || c > '9') {
271	                continue;
272	            }
273	            int digit = c - '0';
274	            if (doubling) {
275	                digit *= 2;
276	                if (digit > 9) {
277	                    digit -= 9;
278	                }
279	            }
280	            sum += digit;
281	            doubling = !doubling;
282	        }
283	        return (10 - (sum % 10)) % 10;
284	    }
285	
286	    /** Fixed city-to-region table used to derive an owner's locality. */
287	    private static final Map<String, String> CITY_REGION = Map.of(
288	        "Sydney", "NSW",
289	        "Melbourne", "VIC",
290	        "Brisbane", "QLD");
291	
292	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
293	    public static final String UNKNOWN_REGION = "UNKNOWN";
294	
295	    /**
296	     * The canonical region for a city, derived from the fixed city-to-region table
297	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
298	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
299	     * source of the city-to-region mapping, shared by every rule that is keyed by
300	     * region so the mapping is never re-derived elsewhere.
301	     */
302	    public static String regionOf(String city) {
303	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
304	    }
305	
306	    /**
307	     * The owner's locality: the {@code <REGION>} component of the {@link #getCustomerCode()
308	     * customerCode} (its prefix up to the first {@code '-'}), which is the region derived from
309	     * the owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no
310	     * known region). Locality is read from the region-and-hash identity so it never re-derives
311	     * a region of its own; it is {@link #UNKNOWN_REGION} for an owner that has no customerCode.
312	     */
313	    public String getLocality() {
314	        if (this.customerCode == null) {
315	            return UNKNOWN_REGION;
316	        }
317	        int dash = this.customerCode.indexOf('-');
318	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
319	    }
320	
321	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
322	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
323	        "NSW", "Australia/Sydney",
324	        "VIC", "Australia/Melbourne",
325	        "QLD", "Australia/Brisbane");
326	
327	    /**
328	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
329	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
330	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
331	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
332	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
333	     */
334	    public String getTimezone() {
335	        return REGION_TIMEZONE.get(getLocality());
336	    }
337	
338	    /**
339	     * The region derived from this owner's postcode alone: the region whose fixed
340	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
341	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
342	     * component built into the owner's customer code at creation and, through it, the source of the
343	     * owner's {@linkplain #getLocality() locality}. It is the single place a region is read from an
344	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
345	     */
346	    public String getRegion() {
347	        return regionOfPostcode(this.postcode);
348	    }
349	
350	    /**
351	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
352	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
353	     * no known range.
354	     */
355	    private static String regionOfPostcode(String postcode) {
356	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
357	            return null;
358	        }
359	        int value = Integer.parseInt(postcode);
360	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
361	            int[] range = entry.getValue();
362	            if (value >= range[0] && value <= range[1]) {
363	                return entry.getKey();
364	            }
365	        }
366	        return null;
367	    }
368	
369	    /**
370	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
371	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
372	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
373	     */
374	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
375	        "NSW", new int[] {2000, 2099},
376	        "VIC", new int[] {3000, 3099},
377	        "QLD", new int[] {4000, 4099});
378	
379	    /**
380	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
381	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
382	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
383	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
384	     * city with no known region accepts any 4-digit postcode.
385	     */
386	    public boolean isPostcodeValid() {
387	        if (this.postcode == null) {
388	            return true;
389	        }
390	        if (!this.postcode.matches("[0-9]{4}")) {
391	            return false;
392	        }
393	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
394	        if (range == null) {
395	            return true;
396	        }
397	        int value = Integer.parseInt(this.postcode);
398	        return value >= range[0] && value <= range[1];
399	    }
400	
401	    /**
402	     * The national (subscriber) digit count required by each known country calling code, keyed by
403	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
404	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
405	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
406	     * re-derived elsewhere.
407	     */
408	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
409	        "1", 10,
410	        "61", 9);
411	
412	    /**
413	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
414	     * E.164 digit string, choosing the longest matching code known to
415	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
416	     * country code. This is the single place a country code is read from an E.164 number, so every
417	     * rule keyed by that code shares one derivation.
418	     */
419	    private static String countryCodeOf(String e164Digits) {
420	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
421	            .filter(e164Digits::startsWith)
422	            .max(Comparator.comparingInt(String::length))
423	            .orElse(null);
424	    }
425	
426	    /**
427	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
428	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
429	     * known code wins; a number whose country code is not recognised passes this check (its length is
430	     * then governed only by the general E.164 bound), while a recognised code must be followed by
431	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
432	     */
433	    public static boolean hasValidNationalLength(String e164Digits) {
434	        String countryCode = countryCodeOf(e164Digits);
435	        if (countryCode == null) {
436	            return true;
437	        }
438	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
439	    }
440	
441	    /**
442	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
443	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
444	     * gain 3 when the owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. The email,
445	     * namesake and household factors are available on creation; the tenure factor is reached only
446	     * once tenure grows beyond 365 days.
447	     */
448	    public Integer getMembershipPoints() {
449	        int points = 0;
450	        if (hasEmail()) {
451	            points += 2;
452	        }
453	        if (hasNoNamesakes()) {
454	            points += 1;
455	        }
456	        if (hasLargeHousehold()) {
457	            points += 2;
458	        }
459	        if (hasTenureBeyondOneYear()) {
460	            points += 3;
461	        }
462	        return points;
463	    }
464	
465	    /**
466	     * The owner's membership level, a number from 1 to 4 derived from {@linkplain #getMembershipPoints()
467	     * membershipPoints}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or
468	     * more.
469	     */
470	    public Integer getMembershipLevel() {
471	        int points = getMembershipPoints();
472	        if (points >= 6) {
473	            return 4;
474	        }
475	        if (points >= 4) {
476	            return 3;
477	        }
478	        if (points >= 2) {
479	            return 2;
480	        }
481	        return 1;
482	    }
483	
484	    /**
485	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
486	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
487	     * known, is treated as not a large household.
488	     */
489	    private boolean hasLargeHousehold() {
490	        return this.householdSize != null && this.householdSize >= 3;
491	    }
492	
493	    /**
494	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
495	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
496	     * email presence so the check is never re-derived elsewhere.
497	     */
498	    private boolean hasEmail() {
499	        return this.email != null && !this.email.isEmpty();
500	    }
501	
502	    /**
503	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
504	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
505	     * not known, is treated as not unique.
506	     */
507	    private boolean hasNoNamesakes() {
508	        return this.namesakeCount != null && this.namesakeCount == 0;
509	    }
510	
511	    /**
512	     * Whether this owner's {@linkplain #getTenureDays() tenure} exceeds 365 days. A newly created owner
513	     * (zero tenure) does not qualify; the threshold is crossed only once tenure grows beyond one year.
514	     */
515	    private boolean hasTenureBeyondOneYear() {
516	        return this.getTenureDays() > 365;
517	    }
518	
519	    /**
520	     * The owner's tenure in whole days: the number of days between the {@link #registrationDate} and
521	     * the current date, or {@code 0} when the registrationDate is not yet set (a newly created owner has
522	     * zero tenure). Never negative.
523	     */
524	    public long getTenureDays() {
525	        if (this.registrationDate == null) {
526	            return 0;
527	        }
528	        return Math.max(0, ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()));
529	    }
530	
531	    /**
532	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
533	     * otherwise {@code 'PHONE'}.
534	     */
535	    public String getContactPreference() {
536	        return hasEmail() ? "EMAIL" : "PHONE";
537	    }
538	
539	    /**
540	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
541	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
542	     * the national digits grouped into threes from the left separated by spaces,
543	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
544	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
545	     * E.164 form, or carries no known country code.
546	     */
547	    public String getTelephoneDisplay() {
548	        if (this.telephone == null || !this.telephone.startsWith("+")) {
549	            return this.telephone;
550	        }
551	        String digits = this.telephone.substring(1);
552	        String countryCode = countryCodeOf(digits);
553	        if (countryCode == null) {
554	            return this.telephone;
555	        }
556	        String national = digits.substring(countryCode.length());
557	        StringBuilder groups = new StringBuilder();
558	        for (int i = 0; i < national.length(); i += 3) {
559	            if (groups.length() > 0) {
560	                groups.append(' ');
561	            }
562	            groups.append(national, i, Math.min(i + 3, national.length()));
563	        }
564	        return "+" + countryCode + " " + groups;
565	    }
566	
567	    /**
568	     * The owner's identity key: the single derived value used for duplicate detection.
569	     * It joins the normalized (E.164) telephone, the email (already lower-cased, or the
570	     * empty string when absent) and the householdId (or the empty string when the owner
571	     * has no household) with {@code '|'}, e.g. {@code '+61412345678|jane@example.test|3C1A9F2B7D4E'}.
572	     * Two owners are duplicates only when their whole identity keys are equal.
573	     */
574	    public String getIdentityKey() {
575	        String telephonePart = this.telephone == null ? "" : this.telephone;
576	        String emailPart = this.email == null ? "" : this.email;
577	        String householdPart = this.householdId == null ? "" : this.householdId;
578	        return telephonePart + "|" + emailPart + "|" + householdPart;
579	    }
580	
581	    protected Set<Pet> getPetsInternal() {
582	        if (this.pets == null) {
583	            this.pets = new HashSet<>();
584	        }
585	        return this.pets;
586	    }
587	
588	    protected void setPetsInternal(Set<Pet> pets) {
589	        this.pets = pets;
590	    }
591	
592	    public List<Pet> getPets() {
593	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
594	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
595	        return Collections.unmodifiableList(sortedPets);
596	    }
597	
598	    public void setPets(List<Pet> pets) {
599	        this.pets = new HashSet<>(pets);
600	    }
601	
602	    public void addPet(Pet pet) {
603	        getPetsInternal().add(pet);
604	        pet.setOwner(this);
605	    }
606	
607	    /**
608	     * Return the Pet with the given name, or null if none found for this Owner.
609	     *
610	     * @param name to test
611	     * @return true if pet name is already in use
612	     */
613	    public Pet getPet(String name) {
614	        return getPet(name, false);
615	    }
616	
617	    /**
618	     * Return the Pet with the given name, or null if none found for this Owner.
619	     *
620	     * @param name to test
621	     * @return true if pet name is already in use
622	     */
623	    public Pet getPet(String name, boolean ignoreNew) {
624	        name = name.toLowerCase();
625	        for (Pet pet : getPetsInternal()) {
626	            if (!ignoreNew || !pet.isNew()) {
627	                String compName = pet.getName();
628	                compName = compName.toLowerCase();
629	                if (compName.equals(name)) {
630	                    return pet;
631	                }
632	            }
633	        }
634	        return null;
635	    }
636	
637	    public Pet getPet(Integer petId) {
638	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
639	    }
640	
641	    @Override
642	    public String toString() {
643	        return new ToStringCreator(this)
644	
645	            .append("id", this.getId())
646	            .append("new", this.isNew())
647	            .append("lastName", this.getLastName())
648	            .append("firstName", this.getFirstName())
649	            .append("address", this.address)
650	            .append("city", this.city)
651	            .append("telephone", this.telephone)
652	            .append("email", this.email)
653	            .toString();
654	    }
655	}
