16	
17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.DayOfWeek;
23	import java.time.LocalDate;
24	import java.util.Collection;
25	import java.util.Comparator;
26	import java.util.List;
27	import java.util.Objects;
28	import java.util.Set;
29	import java.util.stream.Collectors;
30	
31	import org.slf4j.Logger;
32	import org.slf4j.LoggerFactory;
33	import org.springframework.http.HttpHeaders;
34	import org.springframework.http.HttpStatus;
35	import org.springframework.http.ResponseEntity;
36	import org.springframework.samples.petclinic.mapper.OwnerMapper;
37	import org.springframework.samples.petclinic.mapper.PetMapper;
38	import org.springframework.samples.petclinic.mapper.VisitMapper;
39	import org.springframework.samples.petclinic.model.Owner;
40	import org.springframework.samples.petclinic.model.Pet;
41	import org.springframework.samples.petclinic.model.Visit;
42	import org.springframework.samples.petclinic.rest.api.OwnersApi;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.util.UriComponentsBuilder;
55	
56	import jakarta.transaction.Transactional;
57	
58	/**
59	 * @author Vitaliy Fedoriv
60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    private final AddressNormalizer addressNormalizer;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper,
83	                                 AddressNormalizer addressNormalizer) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	        this.addressNormalizer = addressNormalizer;
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
94	        Collection<Owner> owners;
95	        if (lastName != null) {
96	            owners = this.clinicService.findOwnerByLastName(lastName);
97	        } else {
98	            owners = this.clinicService.findAllOwners();
99	        }
100	        if (owners.isEmpty()) {
101	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
102	        }
103	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	
121	        HttpStatus invalid = normalizeAndValidate(owner);
122	        if (invalid != null) {
123	            return new ResponseEntity<>(invalid);
124	        }
125	        if (isDailyLimitReached(owner.getRegistrationDate())) {
126	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
127	        }
128	
129	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
130	        assignHousehold(owner);
131	
132	        HttpStatus conflict = checkForConflicts(owner, sharesHousehold);
133	        if (conflict != null) {
134	            return new ResponseEntity<>(conflict);
135	        }
136	
137	        assignDerivedAttributes(owner, sharesHousehold);
138	        this.clinicService.saveOwner(owner);
139	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
140	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
141	            owner.getMembershipLevel(), owner.getMembershipNumber());
142	        return created(owner);
143	    }
144	
145	    /**
146	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
147	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
148	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
149	     * postcode is checked against its city's region, a registration date in the future is rejected,
150	     * and the effective registration date (the supplied one, or today when none was given) is rolled
151	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
152	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
153	     * otherwise.
154	     */
155	    private HttpStatus normalizeAndValidate(Owner owner) {
156	        if (!normalizeAddress(owner)) {
157	            return HttpStatus.BAD_REQUEST;
158	        }
159	        String telephone = toE164(owner.getTelephone());
160	        if (telephone == null) {
161	            return HttpStatus.BAD_REQUEST;
162	        }
163	        owner.setTelephone(telephone);
164	        if (isDisposableEmail(owner.getEmail())) {
165	            return HttpStatus.BAD_REQUEST;
166	        }
167	        if (!owner.isPostcodeValid()) {
168	            return HttpStatus.BAD_REQUEST;
169	        }
170	        if (owner.getRegistrationDate() != null
171	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
172	            return HttpStatus.BAD_REQUEST;
173	        }
174	        LocalDate effectiveDate = owner.getRegistrationDate() != null
175	            ? owner.getRegistrationDate() : LocalDate.now();
176	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
177	        return null;
178	    }
179	
180	    /**
181	     * Normalize the owner's supplied address into its canonical stored form and report whether an
182	     * address was supplied at all. The raw address is run through the {@link AddressNormalizer}
183	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded) and
184	     * stored back on the owner. Returns {@code true} once a non-blank address has been normalized and
185	     * stored, or {@code false} when no address was supplied (a blank address canonicalises to the
186	     * empty string), in which case the create must be rejected with {@code 400 Bad Request}.
187	     */
188	    private boolean normalizeAddress(Owner owner) {
189	        String address = addressNormalizer.normalize(owner.getAddress());
190	        if (address.isEmpty()) {
191	            return false;
192	        }
193	        owner.setAddress(address);
194	        return true;
195	    }
196	
197	    /**
198	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
199	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
200	     */
201	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
202	        "mailinator.com", "tempmail.com", "guerrillamail.com");
203	
204	    /**
205	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
206	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
207	     * the domain (the part after the last {@code '@'}, compared case-insensitively) is matched
208	     * against the blocklist.
209	     */
210	    private boolean isDisposableEmail(String email) {
211	        if (email == null || email.isEmpty()) {
212	            return false;
213	        }
214	        int at = email.lastIndexOf('@');
215	        if (at < 0) {
216	            return false;
217	        }
218	        String domain = email.substring(at + 1).toLowerCase();
219	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
220	    }
221	
222	    /**
223	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
224	     * deterministically from the owner's lastName and postcode, so every owner sharing that
225	     * lastName and postcode is assigned the same value automatically, independent of whether the
226	     * owner declares it shares a household. The link is assigned before the
227	     * {@link #checkForConflicts(Owner, boolean) conflict checks} because it is part of the owner's
228	     * {@link Owner#getIdentityKey() identity} and feeds its {@link #householdSize(String) household
229	     * size}.
230	     */
231	    private void assignHousehold(Owner owner) {
232	        owner.setHouseholdId(householdId(owner));
233	    }
234	
235	    /**
236	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
237	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
238	     * {@link #isHouseholdDuplicate(Owner) duplicates an existing household} or when its
239	     * {@link #isCityAtCapacity(String) city is already at capacity}. Declaring {@code
240	     * sharesHousehold} bypasses only the household-duplicate block (the owner is then created as a
241	     * declared household member); it does not lift the city-capacity limit. Returns {@code null}
242	     * when the owner clashes with nothing and may be created.
243	     */
244	    private HttpStatus checkForConflicts(Owner owner, boolean sharesHousehold) {
245	        if (!sharesHousehold && isHouseholdDuplicate(owner)) {
246	            return HttpStatus.CONFLICT;
247	        }
248	        if (isCityAtCapacity(owner.getCity())) {
249	            return HttpStatus.CONFLICT;
250	        }
251	        return null;
252	    }
253	
254	    /**
255	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
256	     * {@code Location} header pointing at {@code /api/owners/{id}}.
257	     */
258	    private ResponseEntity<OwnerDto> created(Owner owner) {
259	        HttpHeaders headers = new HttpHeaders();
260	        headers.setLocation(UriComponentsBuilder.newInstance()
261	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
262	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
263	    }
264	
265	    /**
266	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
267	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
268	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
269	     * householdSize}. Each is computed from the owner's own fields together with the owners already
270	     * present, so this runs after the owner has been validated and has passed the duplicate and
271	     * capacity checks, and immediately before it is persisted.
272	     */
273	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
274	        owner.setCustomerCode(customerCode(owner));
275	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
276	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
277	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
278	        assignPossibleDuplicate(owner, sharesHousehold);
279	    }
280	
281	    /**
282	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
283	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
284	     * so it is never flagged. Otherwise, because this runs after the hard
285	     * {@link #isHouseholdDuplicate(Owner) household-duplicate} check, the owner is not a household
286	     * match; it is flagged only when it is a soft match of an existing owner as determined by
287	     * {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
288	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
289	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
290	     */
291	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
292	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
293	        owner.setPossibleDuplicate(match != null);
294	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
295	    }
296	
297	    /**
298	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
299	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
300	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
301	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
302	     * postcode never matches.
303	     */
304	    private Owner findSoftDuplicate(Owner owner) {
305	        if (owner.getPostcode() == null) {
306	            return null;
307	        }
308	        String candidateLastName = normalizeName(owner.getLastName());
309	        return this.clinicService.findAllOwners().stream()
310	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
311	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
312	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
313	            .min(Comparator.comparingInt(Owner::getId))
314	            .orElse(null);
315	    }
316	
317	    /**
318	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
319	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
320	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
321	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
322	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
323	     * every value built from the customer code (the membership number and its check digit) and the
324	     * owner's locality are derived from it.
325	     *
326	     * <p>When the computed code collides with an existing owner's {@code customerCode}, a
327	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the code
328	     * unique, and the de-duplicated code is returned.
329	     */
330	    private String customerCode(Owner owner) {
331	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
332	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
333	        String base = region + "-" + hash8;
334	
335	        Set<String> existingCodes = this.clinicService.findAllOwners().stream()
336	            .map(Owner::getCustomerCode)
337	            .filter(Objects::nonNull)
338	            .collect(Collectors.toSet());
339	
340	        if (!existingCodes.contains(base)) {
341	            return base;
342	        }
343	        int n = 2;
344	        while (existingCodes.contains(base + "-" + n)) {
345	            n++;
346	        }
347	        return base + "-" + n;
348	    }
349	
350	    /**
351	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
352	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
353	     * (business-day) registration date of the owner being created, so owners are counted per
354	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
355	     */
356	    private boolean isDailyLimitReached(LocalDate day) {
357	        long count = this.clinicService.findAllOwners().stream()
358	            .filter(existing -> day.equals(existing.getRegistrationDate()))
359	            .count();
360	        return count >= 100;
361	    }
362	
363	    /**
364	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
365	     * more than 80 owners have already been created for the given business day. Counts the owners
366	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
367	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
368	     * warning.
369	     */
370	    private boolean isBulkSignup(LocalDate day) {
371	        long count = this.clinicService.findAllOwners().stream()
372	            .filter(existing -> day.equals(existing.getRegistrationDate()))
373	            .count();
374	        return count > 80;
375	    }
376	
377	    /**
378	     * Roll a registration date forward onto a business day: when it falls on a Saturday or Sunday,
379	     * advance it to the following Monday; a weekday is returned unchanged.
380	     */
381	    private LocalDate toBusinessDay(LocalDate date) {
382	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
383	            date = date.plusDays(1);
384	        }
385	        return date;
386	    }
387	
388	    /**
389	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
390	     * more owners. Cities are compared case-insensitively.
391	     */
392	    private boolean isCityAtCapacity(String city) {
393	        long count = this.clinicService.findAllOwners().stream()
394	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
395	            .count();
396	        return count >= 50;
397	    }
398	
399	    /**
400	     * The number of existing owners that already share the given firstName and lastName,
401	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
402	     * whitespace runs collapsed). Counted over the owners present before this create.
403	     */
404	    private int namesakeCount(String firstName, String lastName) {
405	        String candidateFirstName = normalizeName(firstName);
406	        String candidateLastName = normalizeName(lastName);
407	        return (int) this.clinicService.findAllOwners().stream()
408	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
409	                && normalizeName(existing.getLastName()).equals(candidateLastName))
410	            .count();
411	    }
412	
413	    /**
414	     * The number of members in this owner's household after this create: the count of existing
415	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
416	     * created. An owner with no household ({@code householdId == null}) is a household of one.
417	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
418	     * does not depend on the order in which household members were created.
419	     */
420	    private int householdSize(String householdId) {
421	        if (householdId == null) {
422	            return 1;
423	        }
424	        long existing = this.clinicService.findAllOwners().stream()
425	            .filter(other -> householdId.equals(other.getHouseholdId()))
426	            .count();
427	        return (int) existing + 1;
428	    }
429	
430	    /**
431	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
432	     * cannot form a valid E.164 number.
433	     *
434	     * <p>A leading '+' and country code are kept when present; otherwise country code
435	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
436	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
437	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
438	     * exactly the national-digit count that code requires (see
439	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
440	     */
441	    private String toE164(String telephone) {
442	        if (telephone == null) {
443	            return null;
444	        }
445	        boolean hasCountryCode = telephone.trim().startsWith("+");
446	        String digits = telephone.replaceAll("\\D", "");
447	        String e164;
448	        if (hasCountryCode) {
449	            e164 = digits;
450	        } else {
451	            if (digits.startsWith("0")) {
452	                digits = digits.substring(1);
453	            }
454	            e164 = "61" + digits;
455	        }
456	        if (e164.length() < 8 || e164.length() > 15) {
457	            return null;
458	        }
459	        if (!Owner.hasValidNationalLength(e164)) {
460	            return null;
461	        }
462	        return "+" + e164;
463	    }
464	
465	    /**
466	     * Whether the candidate owner belongs to a household that already exists, and so must be
467	     * rejected with {@code 409 Conflict} unless it declares {@code sharesHousehold}. The household
468	     * is keyed by the deterministic {@link #householdId(Owner) householdId} (derived from lastName
469	     * and postcode), so any existing owner carrying the same householdId means this owner is a
470	     * second member of an already-registered household. Two owners sharing a lastName and postcode
471	     * are therefore the same household: the second is a household duplicate.
472	     */
473	    private boolean isHouseholdDuplicate(Owner owner) {
474	        String householdId = owner.getHouseholdId();
475	        if (householdId == null) {
476	            return false;
477	        }
478	        return this.clinicService.findAllOwners().stream()
479	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
480	    }
481	
482	    /**
483	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
484	     * to a single space and lower-case. A null value normalizes to the empty string.
485	     */
486	    private String normalizeName(String value) {
487	        if (value == null) {
488	            return "";
489	        }
490	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
491	    }
492	
493	    /**
494	     * A stable shared identifier for the household an owner belongs to, derived deterministically
495	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
496	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
497	     * assigned the same value regardless of the order in which they are created. Formatted as the
498	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
499	     * (an absent postcode contributes the empty string).
500	     */
501	    private String householdId(Owner owner) {
502	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
503	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
504	        return shaHexUpper(key).substring(0, 12);
505	    }
506	
507	    /**
508	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
509	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
510	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
511	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
512	     * {@link #customerCode} keeps the first 8).
513	     */
514	    private String shaHexUpper(String input) {
515	        try {
516	            byte[] digest = MessageDigest.getInstance("SHA-256")
517	                .digest(input.getBytes(StandardCharsets.UTF_8));
518	            StringBuilder sb = new StringBuilder(digest.length * 2);
519	            for (byte b : digest) {
520	                sb.append(String.format("%02x", b));
521	            }
522	            return sb.toString().toUpperCase();
523	        }
524	        catch (NoSuchAlgorithmException e) {
525	            throw new IllegalStateException("SHA-256 not available", e);
526	        }
527	    }
528	
529	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
530	    @Override
531	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
532	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
533	        if (currentOwner == null) {
534	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
535	        }
536	        currentOwner.setAddress(ownerFieldsDto.getAddress());
537	        currentOwner.setCity(ownerFieldsDto.getCity());
538	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
539	        currentOwner.setLastName(ownerFieldsDto.getLastName());
540	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
541	        this.clinicService.saveOwner(currentOwner);
542	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
543	    }
544	
545	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
546	    @Transactional
547	    @Override
548	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
549	        Owner owner = this.clinicService.findOwnerById(ownerId);
550	        if (owner == null) {
551	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
552	        }
553	        this.clinicService.deleteOwner(owner);
554	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
555	    }
556	
557	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
558	    @Override
559	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
560	        Owner owner = this.clinicService.findOwnerById(ownerId);
561	        if (owner == null) {
562	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
563	        }
564	        HttpHeaders headers = new HttpHeaders();
565	        Pet pet = petMapper.toPet(petFieldsDto);
566	        owner.setId(ownerId);
567	        pet.setOwner(owner);
568	        pet.getType().setName(null);
569	        this.clinicService.savePet(pet);
570	        PetDto petDto = petMapper.toPetDto(pet);
571	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
572	            .buildAndExpand(pet.getId()).toUri());
573	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
574	    }
575	
576	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
577	    @Override
578	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
579	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
580	        if (currentOwner != null) {
581	            Pet currentPet = this.clinicService.findPetById(petId);
582	            if (currentPet != null) {
583	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
584	                currentPet.setName(petFieldsDto.getName());
585	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
586	                this.clinicService.savePet(currentPet);
587	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
588	            }
589	        }
590	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
591	    }
592	
593	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
594	    @Override
595	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
596	        HttpHeaders headers = new HttpHeaders();
597	        Visit visit = visitMapper.toVisit(visitFieldsDto);
598	        Pet pet = new Pet();
599	        pet.setId(petId);
600	        visit.setPet(pet);
601	        this.clinicService.saveVisit(visit);
602	        VisitDto visitDto = visitMapper.toVisitDto(visit);
603	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
604	            .buildAndExpand(visit.getId()).toUri());
605	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
606	    }
607	
608	
609	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
610	    @Override
611	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
612	        Owner owner = this.clinicService.findOwnerById(ownerId);
613	        if (owner != null) {
614	            Pet pet = owner.getPet(petId);
615	            if (pet != null) {
616	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
617	            }
618	        }
619	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
620	    }
621	}
